import { describe, expect, it } from "vitest";
import {
  buildTiles,
  checkGallery,
  escapeHtml,
  findGallery,
  readTiles,
  replaceGallery,
  summariseChanges
} from "./gallery.mjs";

const startLine =
  "<!-- demo-videos:start (generated by npm run website:videos from demo-videos.json - do not edit) -->";

function page(body, eol = "\n") {
  return ["<ul>", `    ${startLine}`, body, "    <!-- demo-videos:end -->", "</ul>", ""].join(eol);
}

function video(title, description, status = {}) {
  return { title, description, privacyStatus: "public", embeddable: true, ...status };
}

const tiles = [
  {
    id: "uFJbepHNbZ8",
    title: "First Look & Slideshow",
    description: "Relive Immich’s “On this day” <Memories>.",
    titleSource: "override",
    descriptionSource: "YouTube"
  },
  {
    id: "1v8Ug3xoChE",
    title: "Photos",
    description: "Scroll by date.",
    titleSource: "YouTube",
    descriptionSource: "YouTube"
  }
];

describe("escapeHtml", () => {
  it("escapes markup and writes non-ASCII as numeric references", () => {
    expect(escapeHtml(`Tom & "Jerry" <b>’s</b> 📺`)).toBe(
      "Tom &amp; &quot;Jerry&quot; &lt;b&gt;&#8217;s&lt;/b&gt; &#128250;"
    );
    expect(escapeHtml("It's plain")).toBe("It's plain");
  });
});

describe("buildTiles", () => {
  const entries = [
    { id: "uFJbepHNbZ8", title: "First Look", description: undefined },
    { id: "1v8Ug3xoChE", title: undefined, description: "Own words." }
  ];

  it("prefers overrides and otherwise derives the title and description from YouTube", () => {
    const videos = new Map([
      ["uFJbepHNbZ8", video("Ignored – Immich TV for Samsung", "From YouTube.\n\nMore.")],
      ["1v8Ug3xoChE", video("Photos & Timeline - Immich TV for Samsung", "Ignored.")]
    ]);

    expect(buildTiles(entries, videos)).toEqual([
      {
        id: "uFJbepHNbZ8",
        title: "First Look",
        description: "From YouTube.",
        titleSource: "override",
        descriptionSource: "YouTube"
      },
      {
        id: "1v8Ug3xoChE",
        title: "Photos & Timeline",
        description: "Own words.",
        titleSource: "YouTube",
        descriptionSource: "override"
      }
    ]);
  });

  it("allows Unlisted videos", () => {
    const videos = new Map([
      ["uFJbepHNbZ8", video("A", "B.", { privacyStatus: "unlisted" })],
      ["1v8Ug3xoChE", video("C", "D.")]
    ]);

    expect(buildTiles(entries, videos)).toHaveLength(2);
  });

  it("refuses missing, private and non-embeddable videos, empty text and long descriptions", () => {
    const all = [
      { id: "uFJbepHNbZ8" },
      { id: "1v8Ug3xoChE" },
      { id: "eE3Ncej2mTc" },
      { id: "20XD48TcXJQ" },
      { id: "0fvvx6qAzoo", description: "x".repeat(161) },
      { id: "7h32ceBChKY", title: "Albums" },
      { id: "gctU6KizgTE", description: "x".repeat(160) }
    ];
    const videos = new Map([
      ["1v8Ug3xoChE", video("Private", "Fine.", { privacyStatus: "private" })],
      ["eE3Ncej2mTc", video("Albums", "Fine.", { embeddable: false })],
      ["20XD48TcXJQ", video("Blank", "\n\nSecond paragraph only.")],
      ["0fvvx6qAzoo", video("Long", "Fine.")],
      ["7h32ceBChKY", video("Duplicate", "Fine.")],
      ["gctU6KizgTE", video("Exactly at the limit", "Fine.")]
    ]);
    let message = "";

    try {
      buildTiles(all, videos);
    } catch (error) {
      message = error.message;
    }

    expect(message.split("\n").slice(1)).toEqual([
      "  Tile 1 (uFJbepHNbZ8): YouTube did not return this video. Check the ID and that it exists.",
      "  Tile 2 (1v8Ug3xoChE): the video is private. Make it Public or Unlisted.",
      '  Tile 3 (eE3Ncej2mTc): the video does not allow embedding. Turn on "Allow embedding".',
      '  Tile 4 (20XD48TcXJQ): no description. Start the YouTube description with a sentence, or add a "description" override.',
      `  Tile 5 (0fvvx6qAzoo): the description is 161 characters; keep it to 160. Shorten the first paragraph: "${"x".repeat(161)}"`,
      `  Tile 6 (7h32ceBChKY): the title "Albums" is already tile 3's.`
    ]);
  });
});

describe("replaceGallery", () => {
  it("writes tiles between the markers at the markers' indentation", () => {
    const result = replaceGallery(page("    <li>old</li>"), tiles);
    const lines = result.split("\n");

    expect(lines[0]).toBe("<ul>");
    expect(lines[1]).toBe(`    ${startLine}`);
    expect(lines[2]).toBe("    <li>");
    expect(lines.at(-3)).toBe("    <!-- demo-videos:end -->");
    expect(lines.at(-2)).toBe("</ul>");
    expect(result).not.toContain("old");
    expect(result).toContain('class="video-tile featured"');
    expect(result).toContain(
      '<img src="https://i.ytimg.com/vi/uFJbepHNbZ8/hqdefault.jpg" alt="" width="480" height="360" loading="eager" decoding="async">'
    );
    expect(result).toContain(
      '<img src="https://i.ytimg.com/vi/1v8Ug3xoChE/hqdefault.jpg" alt="" width="480" height="360" loading="lazy" decoding="async">'
    );
    expect(result).toContain('aria-label="Play First Look &amp; Slideshow demo"');
    expect(result).toContain(
      '<span class="video-desc">Relive Immich&#8217;s &#8220;On this day&#8221; &lt;Memories&gt;.</span>'
    );
    expect(replaceGallery(result, tiles)).toBe(result);
  });

  it("keeps CRLF line endings", () => {
    const result = replaceGallery(page("", "\r\n"), tiles);

    expect(result.replace(/\r\n/g, "")).not.toContain("\n");
  });

  it.each([
    ["no markers", "<ul></ul>"],
    ["two start markers", page(`    ${startLine}`)],
    ["the end before the start", "<!-- demo-videos:end -->\n<!-- demo-videos:start -->\n"],
    ["a marker sharing a line", `<ul>${startLine}\n<!-- demo-videos:end -->`]
  ])("refuses a file with %s", (_name, html) => {
    expect(() => findGallery(html)).toThrow();
  });
});

describe("checkGallery", () => {
  const html = replaceGallery(page(""), tiles);
  const entries = [
    { id: "uFJbepHNbZ8", title: "First Look & Slideshow" },
    { id: "1v8Ug3xoChE", description: "Scroll by date." }
  ];

  it("reads generated tiles back", () => {
    expect(readTiles(html)[1]).toEqual({
      href: "https://youtu.be/1v8Ug3xoChE",
      videoId: "1v8Ug3xoChE",
      dataTitle: "Photos",
      thumbnail: "https://i.ytimg.com/vi/1v8Ug3xoChE/hqdefault.jpg",
      title: "Photos",
      description: "Scroll by date."
    });
  });

  it("passes when the tiles match the manifest", () => {
    expect(checkGallery(html, entries)).toEqual([]);
  });

  it("finds reordered, missing and extra videos", () => {
    expect(checkGallery(html, [entries[1], entries[0]])).toEqual([
      "Tile 1 is uFJbepHNbZ8, but demo-videos.json has 1v8Ug3xoChE.",
      "Tile 2 is 1v8Ug3xoChE, but demo-videos.json has uFJbepHNbZ8."
    ]);
    expect(checkGallery(html, [entries[0]])).toEqual([
      "Tile 2 (1v8Ug3xoChE) is not in demo-videos.json."
    ]);
    expect(checkGallery(html, [...entries, { id: "eE3Ncej2mTc" }])).toEqual([
      "Entry 3 (eE3Ncej2mTc) has no tile in index.html."
    ]);
  });

  it("finds a tile whose IDs disagree, or whose text no longer matches an override", () => {
    const edited = html
      .replace("https://i.ytimg.com/vi/1v8Ug3xoChE/", "https://i.ytimg.com/vi/eE3Ncej2mTc/")
      .replace('data-video-title="First Look &amp; Slideshow"', 'data-video-title="Old"');

    expect(checkGallery(edited, [{ ...entries[0], description: "Changed." }, entries[1]])).toEqual([
      "Tile 1 (uFJbepHNbZ8): data-video-title doesn't match the visible title.",
      "Tile 1 (uFJbepHNbZ8): the description doesn't match its override.",
      "Tile 2: href, data-video-id and thumbnail don't share one video ID " +
        "(https://youtu.be/1v8Ug3xoChE, 1v8Ug3xoChE, https://i.ytimg.com/vi/eE3Ncej2mTc/hqdefault.jpg)."
    ]);
    expect(checkGallery(html, [{ ...entries[0], title: "Renamed" }, entries[1]])).toEqual([
      "Tile 1 (uFJbepHNbZ8): the title doesn't match its override."
    ]);
  });
});

describe("summariseChanges", () => {
  it("lists changed IDs, titles and descriptions, and added or removed tiles", () => {
    const before = readTiles(replaceGallery(page(""), tiles));
    const after = [
      { ...tiles[0], id: "eE3Ncej2mTc" },
      { ...tiles[1], description: "New words.", descriptionSource: "override" },
      { ...tiles[1], id: "20XD48TcXJQ", title: "Memories" }
    ];

    expect(summariseChanges(before, after)).toEqual([
      "Tile 1: video ID uFJbepHNbZ8 → eE3Ncej2mTc.",
      "Tile 2: description now from override.",
      'Tile 3 added: 20XD48TcXJQ, "Memories".'
    ]);
    expect(summariseChanges(before, [tiles[0]])).toEqual(["Tile 2 removed (was 1v8Ug3xoChE)."]);
    expect(summariseChanges(before, tiles)).toEqual([]);
  });
});
